// ═══ STATIC INIT THROWS → ExceptionInInitializerError ═══
public class TradingConfig {
    // Static field initialization:
    private static final int MAX_TRADES = Integer.parseInt("NOT_A_NUMBER");
    // ↑ NumberFormatException at class load time!
    // JVM wraps it: ExceptionInInitializerError(cause=NumberFormatException)
    // Class TradingConfig is PERMANENTLY marked ERRONEOUS.
}

// First access:
try {
    new TradingConfig();
} catch (ExceptionInInitializerError e) {
    // e.getCause() → NumberFormatException("NOT_A_NUMBER")
    // FIRST time: you see the REAL cause!
}

// Second access:
try {
    new TradingConfig();
} catch (NoClassDefFoundError e) {
    // NOT ExceptionInInitializerError! NoClassDefFoundError!
    // Original cause is GONE from this error!
    // Message: "Could not initialize class TradingConfig"
    // Developer: "Why? WHAT failed?" — must find the FIRST log entry!
}

// ═══ STATIC BLOCK THROWS ═══
public class DatabasePool {
    private static final DataSource DS;

    static {
        try {
            DS = createPool();  // might throw if DB is down!
        } catch (SQLException e) {
            throw new RuntimeException("Pool init failed", e);
            // RuntimeException → ExceptionInInitializerError
            // DatabasePool class: DEAD. All services depending on it: DEAD.
        }
    }
}

// ═══ FIX: LAZY INITIALIZATION ═══
public class DatabasePool {
    private static volatile DataSource ds;  // not initialized at class load!

    public static DataSource getDataSource() {
        if (ds == null) {
            synchronized (DatabasePool.class) {
                if (ds == null) {
                    ds = createPool();  // initialized on FIRST USE, not class load
                    // If it fails: method throws exception, but class is NOT dead!
                    // Next call can retry!
                }
            }
        }
        return ds;
    }
}
