package com.bank.staticinit;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class StaticInitTest {

    // Class with failing static init
    static class BadConfig {
        static final int VALUE = Integer.parseInt("NOT_A_NUMBER");
        // NumberFormatException during class loading!
    }

    // Class with safe lazy init
    static class SafeConfig {
        private static volatile Integer value;

        static int getValue() {
            if (value == null) {
                value = Integer.parseInt(System.getProperty("config.value", "100"));
            }
            return value;
        }
    }

    @Test
    void staticInit_firstAccess_exceptionInInitializerError() {
        assertThatThrownBy(() -> {
            // Force class loading:
            Class.forName("com.bank.staticinit.StaticInitTest$BadConfig");
        })
        .isInstanceOf(ExceptionInInitializerError.class)
        .hasCauseInstanceOf(NumberFormatException.class);
        // FIRST access: ExceptionInInitializerError with REAL cause!
    }

    @Test
    void staticInit_secondAccess_noClassDefFoundError() {
        // First access — triggers ExceptionInInitializerError:
        try {
            Class.forName("com.bank.staticinit.StaticInitTest$BadConfig");
        } catch (Throwable t) { /* expected */ }

        // SECOND access — class is DEAD:
        assertThatThrownBy(() -> {
            Class.forName("com.bank.staticinit.StaticInitTest$BadConfig");
        })
        .isInstanceOf(NoClassDefFoundError.class);
        // Original cause GONE! Just "Could not initialize class..."
        // Class is PERMANENTLY dead. Only JVM restart fixes it.
    }

    @Test
    void lazyInit_canRetry() {
        // Lazy init: no static block, initialized on first use
        int value = SafeConfig.getValue();
        assertThat(value).isEqualTo(100);
        // If this failed (wrong property), it throws at METHOD level
        // — NOT at class loading level. Class is still alive. Can retry!
    }
}
